def recur(cur, ans: str) -> List[str]:
    if len(cur) <= 0:
        # Empty list means end of recursion, append string and move to next list in ans
        ans.append(cur)
        return [ans]
    elif cur[0] == '(':
        ans_cur = recur(cur[1:], ans)
        for a in ans_cur:
            a.insert(0, '(')
            a.insert(1, ')')
        return [a for a in ans_cur]
    else:
        ans_cur = recur(cur[1:], ans)
        # Append cur[0] to ans_cur if it's not empty
        if cur[0] != ' ':
            # Ignore if cur[0] is not a space
            ans_cur.append(cur[0] + '(')
        # Keep appending cur[0] to all strings in ans_cur recursively
        for a in ans_cur:
            ans_cur.append(cur[0] + ')' + a)
        return [a for a in ans_cur]

