def first_occurance(string: str, character: str) -> int:
    """First occurance of character 'character' inside string 'string'.
    >>> first_occurance('python', 't')
    7
    >>> first_occurance('', '')
    None
    """
    if len(string) == 0 or len(character) == 0:
        return None
    if string[-1] == character:
        return len(string)
    return first_occurance(string[:-1], character)


def last_occurance(string: str, character: str) -> int:
    """Last occurance of character 'character' inside string 'string'.
    >>> last_occurance('python', 't')
    8
    >>> last_occurance('', '')
    None
    """
    if len(string) == 0 or len(character) == 0:
        return None
    if string[0] == character:
        return 0
    return last_occurance(string[1:], character) + 1



