def digit_at(integer_part, digit_position: int) -> int:
    """Return digit in the given position in integer part of the number.
    Return -1 if the position is larger than integer part length.
    >>> digit_at(125030210, 1)
    5
    """
    assert integer_part >= 0, "Given number is less than zero"

    if digit_position > len(integer_part):
        return -1

    last_digit = 0
    for i in range(len(integer_part)):
        if i == digit_position:
            return int(integer_part[i])
        last_digit = int(integer_part[i]) * 10

    return int(last_digit / 10**(digit_position-1))


