def parse_nested_parens_helper(paren_string: str) -> List[int]:
    stack = []  # type: List[int]
    for char in paren_string.split():
        if char == '(':
            stack.append(1)  # each push increases nesting depth by 1
        elif char == ')':
            if len(stack) == 0:
                raise ValueError('Failed to parse parentheses: unexpected closing parenthesis '
                                 'for balanced parentheses')
            else:
                top = stack.pop()
                stack[-1] += top  # each pop decreases nesting depth by the stack's top value
    return stack

return parse_nested_parens_helper(paren_string)

